    faq: [{"q": "האם אפשר לבחור כל צורה של גבה?", "a": "הצורה נקבעת יחד עם המטופל, בתוך גבולות שמתאימים למבנה הפנים. לפני ההליך מסמנים ומציגים את התוכנית."}, {"q": "כמה זמן לוקח התכנון?", "a": "התכנון נעשה בהתייעצות. לרוב מדובר בזמן קצר, ואין צורך בהכנה מיוחדת."}, {"q": "מה אם אני לא מרוצה מהסימון?", "a": "את הסימון משנים עד שהתוכנית מוסכמת. ההליך מתחיל רק אחרי אישור המטופל."}],
